  const { result } = renderHook(() => useIntersection());
  act(() => cb([{ isIntersecting: true }] as any, {} as any));
  expect(result.current.isVisible).toBe(true);
  vi.unstubAllGlobals();
});

test('isVisible becomes false when no longer intersecting', () => {
  let cb: IntersectionObserverCallback;
  vi.stubGlobal('IntersectionObserver', vi.fn((fn: IntersectionObserverCallback) => {
    cb = fn;
    return { observe: vi.fn(), disconnect: vi.fn() };
  }));
  const { result } = renderHook(() => useIntersection());
  act(() => cb([{ isIntersecting: true }] as any, {} as any));
  act(() => cb([{ isIntersecting: false }] as any, {} as any));
  expect(result.current.isVisible).toBe(false);
  vi.unstubAllGlobals();
});

