  const disconnectSpy = vi.fn();
  vi.stubGlobal('IntersectionObserver', vi.fn(() => ({ observe: vi.fn(), disconnect: disconnectSpy })));
  const { unmount } = renderHook(() => useIntersection());
  unmount();
  expect(disconnectSpy).toHaveBeenCalled();
  vi.unstubAllGlobals();
